// Generated by Eva, the evaluation tool. Types for ./report.js, so a TypeScript import typechecks.
/** Who a reported call is for. Every field optional. */
export interface EvalCallContext {
  anonId?: string;
  episodeId?: string;
  attempt?: number;
  userTurn?: string;
}

/** Wrap a model client so every call whose prompt Eva knows reports itself. Returns the same client. */
export declare function withEval<T>(
  client: T,
  context?: EvalCallContext | (() => EvalCallContext),
): T;
